var btn = root.querySelector('.mtp-menu-cross-btn');
var now = root.querySelector('.mtp-menu-cross-now b');
var items = root.querySelectorAll('.mtp-menu-cross-item');
var open = false;
function set(v){
  open = v;
  root.classList.toggle('mtp-menu-cross-on', v);
  btn.setAttribute('aria-expanded', v ? 'true' : 'false');
  btn.setAttribute('aria-label', v ? 'Close menu' : 'Open menu');
}
btn.addEventListener('click', function(){ set(!open); });
Array.prototype.forEach.call(items, function(it, i){
  if (i === 0) it.setAttribute('aria-current', 'true');
  it.addEventListener('click', function(){
    Array.prototype.forEach.call(items, function(o){ o.removeAttribute('aria-current'); });
    it.setAttribute('aria-current', 'true');
    now.textContent = it.firstChild.textContent.trim();
    set(false);
    btn.focus();
  });
});
root.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && open){ set(false); btn.focus(); }
});

