var toggle = root.querySelector('.mtp-play-pause-toggle');
var glyph = root.querySelector('.mtp-play-pause-d');
var fill = root.querySelector('.mtp-play-pause-fill');
var knob = root.querySelector('.mtp-play-pause-knob');
var clock = root.querySelector('.mtp-play-pause-now');
var state = root.querySelector('.mtp-play-pause-state');
var track = root.querySelector('.mtp-play-pause-track');
var skips = root.querySelectorAll('.mtp-play-pause-skip');
var PLAY = [6,4, 12.5,8, 12.5,16, 6,20, 12.5,8, 19,12, 19,12, 12.5,16];
var PAUSE = [6,4, 10.5,4, 10.5,20, 6,20, 13.5,4, 18,4, 18,20, 13.5,20];
var TOTAL = 232;
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var m = 0, mTo = 0, playing = false, at = 0, last = 0, live = false;

function draw(t){
  var p = [], i;
  for (i = 0; i < 16; i++) p.push((PLAY[i] + (PAUSE[i] - PLAY[i]) * t).toFixed(2));
  glyph.setAttribute('d', 'M' + p[0] + ' ' + p[1] + 'L' + p[2] + ' ' + p[3] + 'L' + p[4] + ' ' + p[5] +
    'L' + p[6] + ' ' + p[7] + 'ZM' + p[8] + ' ' + p[9] + 'L' + p[10] + ' ' + p[11] + 'L' + p[12] + ' ' + p[13] +
    'L' + p[14] + ' ' + p[15] + 'Z');
}
function fmt(s){ s = Math.max(0, Math.round(s)); return Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2); }
function paint(){
  var pct = (at / TOTAL) * 100;
  fill.style.width = pct + '%';
  knob.style.left = pct + '%';
  clock.textContent = fmt(at);
  track.setAttribute('aria-valuenow', Math.round(at));
  track.setAttribute('aria-valuetext', fmt(at));
}
function frame(ts){
  if (!root.isConnected){ live = false; return; }
  var dt = last ? (ts - last) / 1000 : 0;
  last = ts;
  if (Math.abs(mTo - m) > 0.002) m += (mTo - m) * Math.min(1, dt * 9);
  else m = mTo;
  draw(m);
  if (playing){
    at += dt;
    if (at >= TOTAL){ at = TOTAL; setPlaying(false); }
    paint();
  }
  if (playing || m !== mTo){ requestAnimationFrame(frame); } else { live = false; last = 0; }
}
function run(){ if (!live){ live = true; last = 0; requestAnimationFrame(frame); } }
function setPlaying(v){
  playing = v;
  mTo = v ? 1 : 0;
  root.classList.toggle('mtp-play-pause-on', v);
  toggle.setAttribute('aria-pressed', v ? 'true' : 'false');
  toggle.setAttribute('aria-label', v ? 'Pause' : 'Play');
  state.textContent = v ? 'Playing' : 'Paused';
  if (calm){ m = mTo; draw(m); }
  run();
}
function seek(v){ at = Math.max(0, Math.min(TOTAL, v)); paint(); }
toggle.addEventListener('click', function(){ setPlaying(!playing); });
skips[0].addEventListener('click', function(){ seek(0); });
skips[1].addEventListener('click', function(){ seek(at + 15); });
track.addEventListener('click', function(e){
  var r = track.getBoundingClientRect();
  seek(((e.clientX - r.left) / r.width) * TOTAL);
});
track.addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight'){ seek(at + 5); e.preventDefault(); }
  else if (e.key === 'ArrowLeft'){ seek(at - 5); e.preventDefault(); }
  else if (e.key === 'Home'){ seek(0); e.preventDefault(); }
  else if (e.key === 'End'){ seek(TOTAL); e.preventDefault(); }
});
draw(0);
paint();

