var tabs = [].slice.call(root.querySelectorAll('.mtp-view-morph-tab'));
var pill = root.querySelector('.mtp-view-morph-pill');
var MODES = ['grid', 'list', 'cols'];
function place(tab){
  var r = tab.getBoundingClientRect();
  var p = tab.parentNode.getBoundingClientRect();
  if (!r.width) return;
  pill.style.width = r.width + 'px';
  pill.style.transform = 'translateX(' + (r.left - p.left) + 'px)';
}
function pick(tab, focus){
  tabs.forEach(function(t){
    var on = t === tab;
    t.setAttribute('aria-selected', on ? 'true' : 'false');
    t.tabIndex = on ? 0 : -1;
  });
  MODES.forEach(function(m){ root.classList.remove('mtp-view-morph-' + m); });
  root.classList.add('mtp-view-morph-' + tab.getAttribute('data-mode'));
  place(tab);
  if (focus) tab.focus();
}
tabs.forEach(function(t, i){
  t.addEventListener('click', function(){ pick(t, false); });
  t.addEventListener('keydown', function(e){
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft'){
      e.preventDefault();
      pick(tabs[(i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length], true);
    }
  });
});
requestAnimationFrame(function(){
  if (!root.isConnected) return;
  place(tabs[0]);
});

