var strips = [];
var value = 4821;

var i, k, d, strip, s;
for (i = 0; i < 4; i++){
  if (i === 1){
    s = document.createElement('span');
    s.className = 'mtp-odometer-sep';
    s.textContent = ',';
    valueEl.appendChild(s);
  }
  d = document.createElement('span');
  d.className = 'mtp-odometer-d';
  strip = document.createElement('span');
  strip.className = 'mtp-odometer-strip';
