.mtp-shape-loader-btn:hover{background:#1a2439;border-color:#3a4d70}
.mtp-shape-loader-btn:active{transform:scale(.96)}
.mtp-shape-loader-btn:focus-visible{outline:2px solid #7aa2ff;outline-offset:2px}
@media (prefers-reduced-motion: reduce){
.mtp-shape-loader-core{transform:none !important;transition:opacity .1s linear}
.mtp-shape-loader-arc{transition:stroke-dashoffset .1s linear}
.mtp-shape-loader-tick{transition:stroke-dashoffset .1s linear}
.mtp-shape-loader-btn{transition:none}
}

