var core = root.querySelector('.mtp-shape-loader-core');
var arc = root.querySelector('.mtp-shape-loader-arc');
var pct = root.querySelector('.mtp-shape-loader-pct');
var label = root.querySelector('.mtp-shape-loader-stagelabel');
var btn = root.querySelector('.mtp-shape-loader-btn');
var LEN = 182.2;
var p = 0, mode = 'run', live = false, last = 0;

function shape(v){
  core.style.borderRadius = (18 + 32 * v).toFixed(1) + '%';
  core.style.transform = 'rotate(' + (v * 260).toFixed(1) + 'deg) scale(' + (1 - 0.3 * v).toFixed(3) + ')';
}
function paint(){
  arc.style.strokeDashoffset = (LEN * (1 - p)).toFixed(1);
  pct.textContent = Math.round(p * 100) + '%';
  shape(p);
  if (mode === 'off') label.textContent = 'Cancelled';
  else if (p >= 1) label.textContent = 'Upload complete';
  else if (p > 0.82) label.textContent = 'Finishing up';
  else if (p > 0.44) label.textContent = 'Optimising';
  else label.textContent = 'Uploading';
}
function frame(ts){
  if (!root.isConnected){ live = false; return; }
  var dt = last ? Math.min(0.05, (ts - last) / 1000) : 0;
  last = ts;
  if (mode === 'run'){
    p += dt * (0.16 + 0.2 * (1 - p));
    if (p >= 1){
      p = 1;
      mode = 'done';
      root.classList.add('mtp-shape-loader-done');
      btn.textContent = 'Upload another';
    }
    paint();
  }
  if (mode === 'run'){ requestAnimationFrame(frame); } else { live = false; last = 0; }
}
function run(){ if (!live){ live = true; last = 0; requestAnimationFrame(frame); } }
btn.addEventListener('click', function(){
  if (mode === 'run'){
    mode = 'off';
    root.classList.add('mtp-shape-loader-off');
    btn.textContent = 'Retry';
    paint();
    return;
  }
  root.classList.remove('mtp-shape-loader-done');
  root.classList.remove('mtp-shape-loader-off');
  p = 0; mode = 'run';
  btn.textContent = 'Cancel';
  paint();
  run();
});
paint();
run();
